components.variantCss:
#wemd .wemd-hero-banner[data-variant="hero-banner-creator-featured"] {
  background: linear-gradient(135deg, #3B82F6, rgb(19,90,206));
  color: #fff;
  padding: 2.5em 1.5em;
  border-radius: 12px;
  text-align: center;
}
#wemd .wemd-hero-banner[data-variant="hero-banner-creator-featured"] .wemd-hero-title {
  font-size: 1.75em;
  font-weight: 700;
  margin: 0 0 0.5em;
  color: #fff;
}
#wemd .wemd-hero-banner[data-variant="hero-banner-creator-featured"] .wemd-hero-subtitle {
  font-size: 1em;
  opacity: 0.9;
  color: rgba(255,255,255,0.9);
}

#wemd .wemd-code-block[data-variant="code-block-creator-default"] {
  background: #1E293B;
  color: #E2E8F0;
  border-radius: 8px;
  padding: 1.25em;
  font-family: "JetBrains Mono", "Fira Code", monospace;
  font-size: 0.85em;
  overflow-x: auto;
  margin: 1.25em 0;
}

#wemd .wemd-steps[data-variant="steps-creator-default"] {
  counter-reset: step;
  padding: 0;
  list-style: none;
}
#wemd .wemd-steps[data-variant="steps-creator-default"] .wemd-step {
  counter-increment: step;
  padding: 0.75em 0 0.75em 2.5em;
  position: relative;
  border-left: 2px solid #3B82F6;
  margin-left: 1em;
}
#wemd .wemd-steps[data-variant="steps-creator-default"] .wemd-step::before {
  content: counter(step);
  position: absolute;
  left: -1em;
  top: 0.75em;
  width: 2em;
  height: 2em;
  background: #3B82F6;
  color: #fff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85em;
  font-weight: 600;
}
